"""Build the published subset of the classroom repository for GitHub Pages."""
from pathlib import Path
from html import escape
import json, re, shutil
from urllib.parse import urlsplit, unquote
ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'docs'
MARKER = '.generated-by-doodle-minds'
if OUT.exists():
    if OUT.is_symlink() or not (OUT / MARKER).is_file():
        raise RuntimeError('Refusing to replace a directory not generated by this builder.')
    shutil.rmtree(OUT)
OUT.mkdir()
(OUT / MARKER).write_text('Generated by tools/build-pages.py\n')
(OUT / '.nojekyll').touch()
entries = json.loads((ROOT / 'courses.json').read_text())
published = [e for e in entries if e['published']]
if not published:
    raise ValueError('Select at least one completed lesson for publishing.')
for e in published:
    if not re.fullmatch(r'lesson-\d{2}', e['id']) or e['status'] != 'ready':
        raise ValueError('Only completed lesson folders may be published.')
    src = ROOT / e['id']
    dst = OUT / e['id']
    dst.mkdir()
    for p in src.iterdir():
        if p.name == 'index.html' or (p.suffix in {'.js', '.css'} and '.test.' not in p.name):
            shutil.copy2(p, dst / p.name)
    shutil.copytree(src / 'assets', dst / 'assets')
    pdf = ROOT / e['worksheet']
    if not pdf.is_file() or pdf.suffix != '.pdf' or ROOT not in pdf.resolve().parents:
        raise ValueError('Missing or invalid worksheet PDF.')
    target = OUT / e['worksheet']
    target.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(pdf, target)
(OUT / 'assets').mkdir()
shutil.copy2(ROOT / 'lesson-01/assets/doodle-minds-logo.png', OUT / 'assets/logo.png')
pumpkin = '''<svg viewBox="0 0 280 200" aria-hidden="true"><path d="M145 57q-6-25 16-30" stroke="#698568" stroke-width="10" fill="none" stroke-linecap="round"/><ellipse cx="140" cy="113" rx="79" ry="66" fill="#e8a066"/><ellipse cx="140" cy="113" rx="52" ry="66" fill="#f1b277"/><ellipse cx="140" cy="113" rx="26" ry="66" fill="#f6c590"/><g fill="#70513e"><circle cx="117" cy="106" r="6"/><circle cx="163" cy="106" r="6"/></g><path d="M116 129q24 27 48 0" stroke="#70513e" stroke-width="5" fill="none" stroke-linecap="round"/><path d="M31 39l3-9 3 9 9 3-9 3-3 9-3-9-9-3zM239 152l3-9 3 9 9 3-9 3-3 9-3-9-9-3z" fill="#d8b965"/></svg>'''
cards = []
for e in published:
    cards.append(f'''<article class="lesson"><div class="art">{pumpkin}<span>LESSON {int(e['id'][-2:]):02d}</span></div><div class="copy"><p class="eyebrow">PICTURES · PREDICTIONS · PLAY</p><h2>{escape(e['title'])}</h2><p>Help Pip prepare his pumpkin party.<br>Choose, test and explain your picture plan.</p><div class="links"><a class="primary" href="{e['id']}/">Open the lesson <span aria-hidden="true">↗</span></a><a href="{escape(e['worksheet'])}">Printable worksheet PDF</a></div></div></article>''')
page = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#fff7e8"><title>Doodle Minds · Pumpkin Party lessons</title><style>
*{box-sizing:border-box}body{margin:0;background:#fff7e8;color:#294f45;font-family:'Trebuchet MS',sans-serif}header,main,footer{max-width:1050px;margin:auto;padding:24px}header{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #d8dec8}header img{width:88px;height:auto}header span,.eyebrow{font-size:11px;letter-spacing:1.8px;font-weight:bold;color:#71826b}main{padding-top:48px;padding-bottom:48px}h1{font:normal clamp(38px,5vw,62px)/1.1 Georgia,serif;letter-spacing:-1.5px;margin:12px 0 18px}.intro{font-size:19px;line-height:1.6;max-width:620px;margin:0 0 34px}.lesson{display:grid;grid-template-columns:.85fr 1.4fr;background:#fffcf4;border:1px solid #cbd4b8;border-radius:26px;overflow:hidden;box-shadow:0 7px 0 #d7dbc440;margin-top:24px}.art{background:#e9efd9;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:28px}.art svg{width:100%;max-width:280px}.art span{font-size:11px;font-weight:bold;letter-spacing:2px;padding:8px 13px;border-radius:9px;background:#f4d18a}.copy{padding:36px}h2{font:normal 38px/1.1 Georgia,serif;margin:12px 0}.copy>p:not(.eyebrow){font-size:17px;line-height:1.6;margin:0 0 24px}.links{display:flex;flex-wrap:wrap;align-items:center;gap:19px}.links a{color:#294f45;font-size:14px}.links .primary{background:#294f45;color:#fff7e8;border-radius:12px;text-decoration:none;font-size:16px;padding:14px 19px;font-weight:bold}.primary span{margin-left:12px}a:focus-visible{outline:3px solid #b5795c;outline-offset:5px}footer{font-size:12px;line-height:1.6;color:#71826b;border-top:1px solid #d8dec8}@media(max-width:640px){header,main,footer{padding:20px}header span{max-width:150px;line-height:1.5;text-align:right}main{padding-top:32px}.lesson{grid-template-columns:1fr}.art{padding:16px}.art svg{height:160px}.copy{padding:25px}.intro{font-size:17px}h2{font-size:34px}.links{align-items:flex-start;flex-direction:column}}
</style></head><body><header><img src="assets/logo.png" alt="Doodle Minds"><span>CLASSROOM LESSONS · AGES 5–7</span></header><main><p class="eyebrow">PIP’S PUMPKIN PARTY</p><h1>Picture plans for a little party.</h1><p class="intro">Story-led computer science adventures.<br>Explore together on screen, then make and test a paper creation.</p>CARDS</main><footer>Teacher-operated lessons · English picture instructions · Printable A4 worksheets</footer></body></html>'''
(OUT / 'index.html').write_text(page.replace('CARDS', '\n'.join(cards)))
# Check direct page assets and worksheet links under a repository-relative URL.
for p in OUT.rglob('*'):
    if p.suffix not in {'.html', '.js'}:
        continue
    content = p.read_text()
    refs = re.findall(r'(?:src|href)=[\'"]([^\'"]+)[\'"]', content)
    refs += re.findall(r'"src":\s*"([^"]+)"', content)
    for ref in refs:
        parts = urlsplit(ref)
        if parts.scheme or ref.startswith('#') or not parts.path or '${' in ref:
            continue
        resolved = (p.parent / unquote(parts.path)).resolve()
        if OUT.resolve() not in resolved.parents or not resolved.exists():
            raise ValueError(f'Broken local link in {p.relative_to(OUT)}: {ref}')
print(f'Built {len(published)} published lesson(s); local assets and PDF links verified.')
